import { readFileSync } from 'node:fs'
import path from 'node:path'
import { describe, expect, it } from 'vitest'
import { astar, dijkstraCostToGoal } from '../nav/astar'

/** Golden cases generated by Python (marsx.nav.fixtures): exact paths, cost within 1e-9. */
const file = path.resolve(import.meta.dirname, '../../../../../packages/schemas/fixtures/nav/cases.json')

interface Case {
  name: string
  rows: number
  cols: number
  cost: (number | null)[]
  start: [number, number]
  goal: [number, number]
  expected: { status: string; path?: [number, number][]; cost?: number; costToGoal?: (number | null)[] }
}
const doc = JSON.parse(readFileSync(file, 'utf8')) as { specVersion: string; cases: Case[] }

const STATUS = { 'out-of-bounds': 'out_of_bounds', 'start-blocked': 'start_blocked', 'goal-blocked': 'goal_blocked', disconnected: 'no_path' } as const

describe(`nav parity vs python (${doc.specVersion})`, () => {
  it('has the cases', () => expect(doc.cases.length).toBeGreaterThanOrEqual(16))
  for (const c of doc.cases) {
    it(c.name, () => {
      const cost = Float32Array.from(c.cost, (v) => (v === null ? Infinity : v))
      const inBounds = (p: [number, number]) => p[0] >= 0 && p[0] < c.rows && p[1] >= 0 && p[1] < c.cols
      const s = c.start[0] * c.cols + c.start[1]
      const g = c.goal[0] * c.cols + c.goal[1]
      const r = inBounds(c.start) && inBounds(c.goal)
        ? astar(cost, c.rows, c.cols, s, g)
        : ({ status: 'no-route', cause: 'out-of-bounds', expanded: 0 } as const)
      if (c.expected.status === 'ok') {
        expect(r.status).toBe('ok')
        if (r.status !== 'ok') return
        const cells = Array.from(r.path, (i) => [Math.floor(i / c.cols), i % c.cols])
        expect(cells).toEqual(c.expected.path)
        expect(Math.abs(r.cost - c.expected.cost!)).toBeLessThan(1e-9)
      } else {
        expect(r.status).toBe('no-route')
        if (r.status === 'no-route') expect(STATUS[r.cause]).toBe(c.expected.status)
      }
      if (c.expected.costToGoal) {
        const d = dijkstraCostToGoal(cost, c.rows, c.cols, g)
        c.expected.costToGoal.forEach((v, i) => {
          if (v === null) expect(d[i]).toBe(Infinity)
          else expect(Math.abs(d[i]! - v)).toBeLessThan(1e-6) // f32 cost inputs, f64 sums
        })
      }
    })
  }
})
